-- Weekly Arena 2026-W44: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W44', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-10-31T00:00:00.000Z', '2026-11-07T00:00:00.000Z', 60, 'published', $WKdf74349a298d$[{"id":"wk-2026-w44-01-4deb","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $22$ and $4$ and each non-parallel side has length $15$. Find its area.","type":"text","correctAnswer":"156","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $9$ and hypotenuse $15$.","solution":"The height is $\\sqrt{15^2-9^2}=12$, so the area is $\\tfrac12(22+4)(12)=156$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w44-02-7727","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $19$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"665","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=19$, i.e. $665$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w44-03-b551","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 2 \\pmod{7}$, $n\\equiv 2 \\pmod{11}$, $n\\equiv 2 \\pmod{5}$.","type":"text","correctAnswer":"2","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $2$ modulo $385$, and $2$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w44-04-8041","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 6$. Find $x^{6} + \\dfrac{1}{x^{6}}$.","type":"text","correctAnswer":"39202","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=6T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=6$ the recurrence gives $T_{6}=39202$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w44-05-2065","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $6$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=1$. Find $PA + PB + PT$.","type":"text","correctAnswer":"43","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=6^2/1=36$, so the sum is $1+36+6=43$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w44-06-14cf","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(7,9)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(6,4)$?","type":"text","correctAnswer":"10180","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{16}{7}-\\binom{10}{6}\\binom{6}{1}=10180$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w44-07-8f21","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 639$ are relatively prime to $30$?","type":"text","correctAnswer":"170","hint":"Remove multiples of 2, 3, 5 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 2, 3, 5 leaves $170$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w44-08-9041","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{48} \\left\\lfloor \\frac{5k}{12} \\right\\rfloor$.","type":"text","correctAnswer":"468","hint":"Write $5k=12q+r$ and track how the remainder cycles with period $12$.","solution":"Evaluating each floor term and adding gives $468$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w44-09-290a","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 5-tuples $(x_1,\\dots,x_5)$ of non-negative integers satisfy $x_1+\\cdots+x_5=18$ with every $x_i\\le 7$?","type":"text","correctAnswer":"2460","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $2460$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2026-w44-10-596b","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 6t + 4 = 0$. Find the remainder when $r^{6} + s^{6}$ is divided by $1000$.","type":"text","correctAnswer":"608","hint":"Let $S_k=r^k+s^k$. Then $S_k=6S_{k-1}-4S_{k-2}$, with $S_0=2$, $S_1=6$.","solution":"Using $S_k=6S_{k-1}-4S_{k-2}$ from $S_0=2$, $S_1=6$ gives $S_{6}=20608$, whose remainder modulo $1000$ is $608$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WKdf74349a298d$::jsonb
